{"tool": "sql", "args": {"query": "WITH RECURSIVE split(HTL_material, rest) AS (SELECT '', HTL_stack_sequence || ' | ' FROM devices WHERE Cell_architecture = 'nip' AND JV_default_PCE > 20 UNION ALL SELECT trim(substr(rest, 1, instr(rest, ' | ') - 1)), substr(rest, instr(rest, ' | ') + 3) FROM split WHERE rest != '') SELECT HTL_material, COUNT(*) as count FROM split WHERE HTL_material != '' GROUP BY HTL_material ORDER BY count DESC LIMIT 20;"}}
